import sys
from pathlib import Path

root = Path.cwd()
patch = Path(sys.argv[1]).read_text()
if not patch.startswith('*** Begin Patch'):
    raise SystemExit('patch must start with *** Begin Patch')

lines = patch.splitlines()
i = 1
while i < len(lines) and lines[i] "'!= '"'*** End Patch':
    line = lines[i]
    if line.startswith('*** Add File: '):
        path = root / line[len('*** Add File: '):]
        i += 1
        content = []
        while i < len(lines) and not lines[i].startswith('*** '):
            if lines[i].startswith('+'):
                content.append(lines[i][1:])
            i += 1
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text('\\n'.join(content) + '\\n')
    elif line.startswith('*** Update File: '):
        path = root / line[len('*** Update File: '):]
        old = path.read_text().splitlines()
        i += 1
        hunk = []
        while i < len(lines) and not lines[i].startswith('*** '):
            hunk.append(lines[i])
            i += 1
        while hunk and not hunk[0].startswith('@@'):
            hunk.pop(0)
        while hunk and not hunk[-1].startswith('@@'):
            hunk.pop()
        if len(hunk) % 2:
            raise SystemExit(f'unbalanced hunk for {path}')
        headers = [index for index, value in enumerate(hunk) if value.startswith('@@')]
        current = 0
        result = []
        removed = 0
        for index, value in enumerate(old):
            while current < len(headers):
                header = hunk[headers[current]]
                start = int(header.split()[1].lstrip('-').split(',')[0])
                if index + 1 >= start + removed:
                    break
            else:
                result.append(value)
                continue
            result.append(value)
        # apply as a simple whole-file replacement hunk
        additions = [value[1:] for value in hunk[1:] if value.startswith('+')]
        removals = [value[1:] for value in hunk[1:] if value.startswith('-')]
        text = '\\n'.join(result)
        for removal in removals:
            if removal not in text:
                raise SystemExit(f'cannot remove:\\n{removal}')
            text = text.replace(removal, '', 1)
        if additions:
            raise SystemExit('additions require custom handling')
        path.write_text(text if text.endswith('\\n') else text + '\\n')
    else:
        raise SystemExit(f'unknown patch line: {line}')
if i >= len(lines) or lines[i] "'!= '"'*** End Patch':
    raise SystemExit('missing *** End Patch')
