): ChartData['series']['data'][number]['data'][number] {
  return {
    x: point.timestamp,
    y: point.value,
    custom: {seriesIndex},
  };
}

export function getSalesChartData(): ChartData {
  return {
    xAxis: {
      type: 'datetime',
      title: {
        text: 'Time',
        style: {
          fontSize: 'var(--g-text-caption-1-font-size)',
          fontColor: 'var(--g-color-text-secondary)',
        },
      },
    },
    yAxis: [
      {
        title: {
          text: 'Sales, units',
          style: {
            fontSize: 'var(--g-text-caption-1-font-size)',
            fontColor: 'var(--g-color-text-secondary)',
          },
        },
      },
    ],
    series: {
      data: salesMetrics.map((metric, seriesIndex) => ({
        id: metric.id,
        name: metric.name,
        type: 'line' as const,
        color: metric.color,
        data: metric.points.map((point) => createSalesPoint(point, seriesIndex)),
      })),
    },
    tooltip: {
      valueFormat: {
        type: 'custom',
        formatter: ({value}) => {
          const metricValue = Number(value);

          return Number.isFinite(metricValue)
            ? \\"'`'"\\"'${metricValue.toFixed(1)} units'"\\"'`
            : String(value);
        },
      },
      headerFormat: {type: '"'date', format: 'DD MMM HH:mm'},
    },
  };
}

export function getMonitoringGraphs(): RawSerieData[] {
  return monitoringMetrics.map((metric) => ({
    id: metric.id,
    name: metric.name,
    type: 'line' as const,
    color: metric.color,
    data: metric.values,
    width: 1,
  }));
}

export function getMonitoringWidgetData() {
  return {
